import json
import re
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from urllib.parse import urljoin, urlsplit, parse_qs, urlencode, urlunsplit
from urllib.request import urlopen

from bs4 import BeautifulSoup
from markdownify import markdownify
from PIL import Image


root = Path(__file__).resolve().parents[2]
source = json.loads(Path(__file__).with_name("source.json").read_text())
output = root / "人人都是UI设计师"
images = output / "images"
images.mkdir(parents=True, exist_ok=True)
origin = "https://x.com/longhaiqwe123/status/2106216781174251724"
soup = BeautifulSoup(source["body"], "html.parser")
assets = []
for index, item in enumerate(source["images"]):
    url = urlsplit(item["src"])
    assert url.hostname == "pbs.twimg.com" and url.path.startswith("/media/")
    query = parse_qs(url.query)
    assert query["format"] == ["jpg"]
    query["name"] = ["orig"]
    original = urlunsplit(url._replace(query=urlencode(query, doseq=True)))
    filename = "00-cover.jpg" if index == 0 else f"{index:02d}.jpg"
    assets.append({"source": original, "file": f"images/{filename}"})
    if index:
        image = soup.find("img", src=item["src"])
        assert image is not None
        image["src"] = f"images/{filename}"
        section = image.find_parent("section")
        image["alt"] = section.get_text().strip() or f"规则 {index:02d} 配图"
        if image.parent.name == "a":
            image.parent.unwrap()

for link in soup.find_all("a", href=True):
    if link.find("img"):
        link.unwrap()
    else:
        link["href"] = urljoin("https://x.com", link["href"])
for span in soup.find_all("span", style=True):
    style = span["style"]
    if "font-weight: bold" in style:
        span.wrap(soup.new_tag("strong"))
    if "font-style: italic" in style:
        span.wrap(soup.new_tag("em"))
for heading in soup.find_all(["h1", "h2"]):
    heading.name = f"h{int(heading.name[1]) + 1}"
for separator in soup.find_all(attrs={"role": "separator"}):
    separator.replace_with(soup.new_tag("hr"))
for wrapper in soup.find_all("div"):
    if wrapper.get("data-block") == "true":
        wrapper.name = "p"
    else:
        wrapper.unwrap()

body = markdownify(str(soup), heading_style="ATX", bullets="-", strip=["section"])
body = re.sub(r"\n{3,}", "\n\n", body).strip()
markdown = (
    f"# {source['title']}\n\n"
    f"作者：龙海（[@longhaiqwe123](https://x.com/longhaiqwe123)）\n\n"
    f"来源：[X 原文]({origin})\n\n"
    f"![文章封面](images/00-cover.jpg)\n\n{body}\n"
)


def download(asset):
    destination = output / asset["file"]
    with urlopen(asset["source"], timeout=45) as response:
        assert response.status == 200
        assert response.headers.get_content_type() == "image/jpeg"
        destination.write_bytes(response.read())
    with Image.open(destination) as image:
        assert image.format == "JPEG"
        dimensions = image.size
        image.verify()
    return {"file": asset["file"], "bytes": destination.stat().st_size, "size": dimensions}


assert len(source["images"]) == 21
assert len(re.findall(r"^### 规则 \d{2}：", markdown, re.M)) == 20
compact = lambda text: re.sub(r"\s+", "", text.replace("\\", "").replace("*", ""))
for text in BeautifulSoup(source["body"], "html.parser").find_all(attrs={"data-text": "true"}):
    assert compact(text.get_text()) in compact(markdown), text.get_text()
with ThreadPoolExecutor(max_workers=4) as pool:
    result = list(pool.map(download, assets))
